from merge import deep_merge


def test_nested_dict_merges_preserving_siblings():
    base = {'db': {'host': 'localhost', 'port': 5432}, 'debug': False}
    override = {'db': {'port': 6543}}
    result = deep_merge(base, override)
    assert result == {'db': {'host': 'localhost', 'port': 6543}, 'debug': False}


def test_lists_are_replaced_not_concatenated():
    base = {'tags': ['a', 'b']}
    override = {'tags': ['c']}
    assert deep_merge(base, override) == {'tags': ['c']}


def test_type_mismatch_override_wins():
    base = {'x': {'nested': 1}}
    override = {'x': 'now a string'}
    assert deep_merge(base, override) == {'x': 'now a string'}


def test_deeply_nested_three_levels():
    base = {'a': {'b': {'c': 1, 'd': 2}}}
    override = {'a': {'b': {'c': 99}}}
    assert deep_merge(base, override) == {'a': {'b': {'c': 99, 'd': 2}}}

